// Admin Home: the "Nearune Admin" dashboard (counts, world map, quality
// checks, costs, voice usage), rendered from the latest stats snapshot that
// the main app saves as admin-stats.json. Markup and script are kept as JSON
// strings so nothing in them is read as template syntax.
import { ADMIN_HEAD, ADMIN_PTR, adminTabs } from "./admin-theme";

const STYLE = "<style>\n/* Layout: one calm column. Night-sky map is the centerpiece; counts above, usage below. */\n:root{--bg:#EEF0F6;--surface:#FFFFFF;--ink:#16193A;--soft:#4F5578;--line:#D5D9E8;--accent:#3B3FB5;--dot:#C2410C;--land:#C9CFE4;--ok:#1F7A4D;--warn:#B45309;--bad:#B3261E;--display:\"Bricolage Grotesque\",system-ui,sans-serif;--mono:\"IBM Plex Mono\",ui-monospace,monospace}\n@media (prefers-color-scheme:dark){:root:not([data-theme=\"light\"]){--bg:#0B0E24;--surface:#141836;--ink:#ECEEFA;--soft:#A3A9CF;--line:#2A305C;--accent:#9AA0FF;--dot:#FFB454;--land:#2A305C;--ok:#5FD39A;--warn:#F2B25C;--bad:#FF8A80;color-scheme:dark}}\n:root[data-theme=\"dark\"]{--bg:#0B0E24;--surface:#141836;--ink:#ECEEFA;--soft:#A3A9CF;--line:#2A305C;--accent:#9AA0FF;--dot:#FFB454;--land:#2A305C;--ok:#5FD39A;--warn:#F2B25C;--bad:#FF8A80;color-scheme:dark}\nbody{background:var(--bg);color:var(--ink);font-family:var(--display);padding-inline:16px;padding-block:24px 48px}\n.wrap{max-width:880px;margin:0 auto;display:flex;flex-direction:column;gap:20px}\nh1{font-size:1.9rem;line-height:1.1;margin:0;font-weight:700;text-wrap:balance}\n.asof{font-family:var(--mono);font-size:.78rem;color:var(--soft);margin:6px 0 0}\n.tiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px}\n.tile{background:var(--surface);border:1px solid var(--line);border-radius:10px;padding:14px 16px;min-width:0}\n.tile .n{font-size:2.6rem;font-weight:700;line-height:1;font-variant-numeric:tabular-nums}\n.tile .l{font-family:var(--mono);font-size:.74rem;letter-spacing:.06em;text-transform:uppercase;color:var(--soft);margin-top:8px}\n.tile .s{font-size:.82rem;color:var(--soft);margin-top:4px}\nsection{background:var(--surface);border:1px solid var(--line);border-radius:10px;padding:16px;min-width:0}\nh2{font-size:1.05rem;margin:0 0 12px;font-weight:700}\nsvg{width:100%;height:auto;display:block}\n.land{fill:var(--land)}\n.pin{fill:var(--dot);fill-opacity:.85;stroke:var(--surface);stroke-width:1.5}\n.cities{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:6px 20px;margin:14px 0 0;padding:0;list-style:none;font-size:.9rem}\n.cities li{display:flex;justify-content:space-between;gap:8px;border-bottom:1px solid var(--line);padding:4px 0;min-width:0}\n.cities span:last-child{font-family:var(--mono);font-variant-numeric:tabular-nums;color:var(--soft)}\n.note{font-size:.8rem;color:var(--soft);margin:10px 0 0;max-width:65ch}\n.meter{height:14px;background:var(--bg);border:1px solid var(--line);border-radius:7px;overflow:hidden}\n.meter i{display:block;height:100%;background:var(--ok)}\n.meter.warn i{background:var(--warn)}.meter.bad i{background:var(--bad)}\n.row{display:flex;flex-wrap:wrap;justify-content:space-between;gap:6px 16px;font-family:var(--mono);font-size:.82rem;margin-top:10px;color:var(--soft)}\n.row b{color:var(--ink);font-weight:500;font-variant-numeric:tabular-nums}\n.qa-sum{display:flex;flex-wrap:wrap;align-items:center;gap:8px 12px;font-size:.95rem}\n.pill{font-family:var(--mono);font-size:.78rem;padding:2px 10px;border-radius:999px;border:1px solid currentColor}\n.pill.ok{color:var(--ok)}.pill.bad{color:var(--bad)}\n.qa-fail{margin:12px 0 0;padding-left:18px;color:var(--bad);font-size:.9rem}\n.qa-fixed{margin:8px 0 0;padding-left:18px;color:var(--soft);font-size:.85rem}\ndetails{margin-top:12px}\nsummary{cursor:pointer;font-size:.9rem;color:var(--accent);font-weight:500}\nsummary:focus-visible{outline:2px solid var(--accent);outline-offset:2px}\n.checklist{list-style:none;margin:10px 0 0;padding:0;display:flex;flex-direction:column;gap:6px;font-size:.9rem}\n.checklist li{display:grid;grid-template-columns:auto 1fr;gap:2px 10px;border-bottom:1px solid var(--line);padding:6px 0;min-width:0}\n.checklist .mk{font-family:var(--mono);font-weight:500}\n.checklist .mk.ok{color:var(--ok)}.checklist .mk.bad{color:var(--bad)}\n.checklist .dt{grid-column:2;font-family:var(--mono);font-size:.78rem;color:var(--soft);overflow-wrap:anywhere}\n.numrow{display:flex;align-items:center;flex-wrap:wrap;gap:6px 10px}\n.pill.na{color:var(--soft)}\n.sub{list-style:none;margin:6px 0 0;padding:0 0 0 14px;border-left:2px solid var(--line);display:flex;flex-direction:column;gap:4px}\n.sub li{display:grid;grid-template-columns:auto 1fr;gap:0 10px;border:0;padding:0;font-size:.82rem}\n.sub .dt{grid-column:auto;margin-left:0}\n.chk{border-bottom:1px solid var(--line);padding:6px 0}\n.chk>summary{list-style:none;display:grid;grid-template-columns:auto 1fr;gap:2px 10px;cursor:pointer;color:var(--ink);font-weight:400}\n.chk>summary::-webkit-details-marker{display:none}\n.chk>summary .dt{grid-column:2}\n.chk>summary::after{content:none}\n.chk .twist{font-family:var(--mono);font-size:.78rem;color:var(--accent)}\n.cityr{display:inline-flex;align-items:center;gap:8px;flex-shrink:0}\n.cities li.click{cursor:pointer}\n.cities li.click:hover span:first-child{text-decoration:underline}\n.cities li.sel{background:var(--bg)}\n.tile.click{cursor:pointer}.tile.click:hover{border-color:var(--soft)}.tile.sel{outline:2px solid var(--soft)}.rooms-panel{margin:14px 0 0;padding:12px 14px;border:1px solid var(--line);border-radius:10px;background:var(--bg)}.rooms-panel h3{margin:0 0 8px;font-size:.95rem;font-weight:600}.rooms-panel ul{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:6px;font-size:.9rem}.rooms-panel li{border-bottom:1px solid var(--line);padding:6px 0}.rooms-panel .pt{color:var(--soft);font-family:var(--mono);font-size:.78rem}\n.who{margin:14px 0 0;padding:12px 14px;border:1px solid var(--line);border-radius:10px;background:var(--bg)}\n.who h3{margin:0 0 8px;font-size:.95rem;font-weight:600}\n.who ul{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:6px;font-size:.9rem}\n.who li{display:flex;flex-wrap:wrap;gap:2px 10px;border-bottom:1px solid var(--line);padding:4px 0}\n.who .pt{color:var(--soft);font-family:var(--mono);font-size:.78rem}\n.cost{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;margin-top:6px}\n.cost .k{font-family:var(--mono);font-size:.78rem;color:var(--soft)}\n.cost .v{font-size:1.5rem;font-weight:600;font-variant-numeric:tabular-nums}\n.alert{position:fixed;top:12px;right:12px;z-index:20;font:inherit}\n.alert-btn{display:flex;align-items:center;gap:8px;border:1px solid var(--bad);background:var(--surface);color:var(--ink);border-radius:999px;padding:6px 12px 6px 8px;font:inherit;font-size:.85rem;font-weight:600;cursor:pointer;box-shadow:0 2px 10px rgba(0,0,0,.18)}\n.alert-btn .dot{min-width:22px;height:22px;border-radius:999px;background:var(--bad);color:#fff;font-size:.78rem;display:flex;align-items:center;justify-content:center;padding:0 6px}\n:root[data-theme=\"dark\"] .alert-btn .dot{color:#2B0A08}\n@media (prefers-color-scheme:dark){:root:not([data-theme=\"light\"]) .alert-btn .dot{color:#2B0A08}}\n.alert-panel{margin-top:8px;width:min(340px,calc(100vw - 24px));background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:12px 14px;box-shadow:0 6px 24px rgba(0,0,0,.22);font-size:.88rem}\n.alert-panel h3{margin:0 0 8px;font-size:.95rem}\n.alert-panel ul{margin:0 0 8px;padding-left:18px;color:var(--bad)}\n.alert-panel li{margin:4px 0}\n.alert-panel a{color:var(--accent);cursor:pointer;text-decoration:underline}\n.pill.sm{font-size:.68rem;padding:0 7px;white-space:nowrap}\n</style>\n";
