const EXTRA_CSS = "<style>.hd{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;flex-wrap:wrap}.hd .tabs{margin-top:4px}.tabs{display:flex;gap:4px;background:var(--surface);border:1px solid var(--line);border-radius:999px;padding:3px}.tabs a{padding:6px 14px;border-radius:999px;text-decoration:none;color:var(--soft);font-weight:600;font-size:.85rem}.tabs a.on{background:var(--accent);color:var(--surface)}.rf{margin:0}.rf button{font:inherit;font-family:var(--mono);font-size:.78rem;color:var(--accent);background:var(--surface);border:1px solid var(--line);border-radius:999px;padding:6px 12px;cursor:pointer}.rf button[disabled]{opacity:.6}.ntc{background:var(--surface);border:1px solid var(--line);border-radius:10px;padding:10px 14px;font-size:.9rem}.alert{top:auto;bottom:16px}</style>";

export function buildAdminHome(statsJson: string | null, secret: string, notice = ""): string {
  const qs = "secret=" + encodeURIComponent(secret);
  let data = "null";
  try { if (statsJson) { JSON.parse(statsJson); data = statsJson; } } catch {}
  const safe = data.replace(/</g, "\\u003c");
  const nav = '<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">' + adminTabs("home", qs) +
    '<form class="rf" method="POST" action="/refresh-stats?' + qs + '" onsubmit="var b=this.querySelector(\'button\');b.disabled=true;b.textContent=\'Refreshing\u2026 up to a minute\';"><button type="submit">&#8635; Refresh now</button></form></div>';
  const msgs: Record<string, string> = { refreshed: "Snapshot refreshed.", refresh_pending: "Still refreshing (quality checks take a minute). Reload this page shortly.", refresh_failed: "Refresh failed. Check the main app logs.", not_configured: "Refresh needs APP_URL and CRON_SECRET on the admin service." };
  const ntc = notice && msgs[notice] ? '<p class="ntc">' + msgs[notice] + "</p>" : "";
  if (data === "null") {
    return head(qs) + '<div class="wrap"><header class="hd"><div><h1>Nearune Admin</h1><p class="asof">No snapshot yet.</p></div>' + nav + "</header>" + ntc +
      '<section><p class="note">The first snapshot is saved a minute after the main app starts, then at 12 AM and 12 PM PT. Tap Refresh now to make one.</p></section></div>' + ADMIN_PTR + '</body></html>';
  }
  return head(qs) + BODY_A.replace("@@NAV@@", nav).replace("@@NOTICE@@", ntc) + "/*DATA*/const DATA = " + safe + ";/*END*/" + BODY_B + ADMIN_PTR + "</body></html>";
}

function head(qs: string): string {
  return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="robots" content="noindex,nofollow">' +
    "<title>Nearune Admin</title>" +
    '<link rel="apple-touch-icon" href="/apple-touch-icon.png"><link rel="manifest" href="/manifest.webmanifest?' + qs + '">' +
    '<meta name="apple-mobile-web-app-capable" content="yes"><meta name="mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-title" content="Nearune Admin">' +
    ADMIN_HEAD + STYLE + EXTRA_CSS + "<style>*{box-sizing:border-box}body{margin:0}</style></head><body>";
}
